import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, rowToJob, nowIso, type Job, type JobRow } from './db.ts';

interface FieldError {
  field: string;
  message: string;
}

const MAX_BODY_BYTES = 1024 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_BODY_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const HEARTBEAT_STALE_MS = 3000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolvePromise, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolvePromise({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isInRangeInteger(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

interface ValidJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates a parsed body, appending one error per offending field. Returns the job values with defaults applied. */
function validateBody(body: Record<string, unknown>, errors: FieldError[]): ValidJob | undefined {
  for (const key of Object.keys(body)) {
    if (!ALLOWED_BODY_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  const { input } = body;
  const inputOk =
    typeof input === 'string' && input.length >= 1 && input.length <= 1000 && input.trim().length > 0;
  if (!inputOk) {
    errors.push({ field: 'input', message: 'Must be a string of 1 to 1000 characters that is not only whitespace.' });
  }

  let steps = 5;
  if (body.steps !== undefined) {
    if (isInRangeInteger(body.steps, 1, 20)) steps = body.steps as number;
    else errors.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  }

  let failAttempts = 0;
  if (body.failAttempts !== undefined) {
    if (isInRangeInteger(body.failAttempts, 0, 5)) failAttempts = body.failAttempts as number;
    else errors.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  }

  if (!inputOk) return undefined;
  return { input: input as string, steps, failAttempts };
}

function jobResponse(row: JobRow): Job {
  return rowToJob(row);
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !KEY_PATTERN.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  let parsed: Record<string, unknown> | undefined;
  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (tooLarge) {
    errors.push({ field: 'body', message: `Body must not exceed ${MAX_BODY_BYTES} bytes.` });
  } else {
    let value: unknown;
    let valid = true;
    try {
      value = JSON.parse(text);
    } catch {
      valid = false;
    }
    if (!valid || value === null || typeof value !== 'object' || Array.isArray(value)) {
      errors.push({ field: 'body', message: 'Body must be a JSON object.' });
    } else {
      parsed = value as Record<string, unknown>;
    }
  }

  const values = parsed ? validateBody(parsed, errors) : undefined;
  if (errors.length > 0 || !values) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const payload = JSON.stringify({ input: values.input, steps: values.steps, failAttempts: values.failAttempts });

  if (key === undefined) {
    const row = insertJob(null, values, payload);
    send(res, 201, jobResponse(row));
    return;
  }

  const outcome = inTransaction(() => {
    const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
    if (existing) {
      return existing.payload === payload
        ? { kind: 'replay' as const, row: existing }
        : { kind: 'conflict' as const };
    }
    return { kind: 'created' as const, row: insertJob(key, values, payload) };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  } else if (outcome.kind === 'replay') {
    send(res, 200, jobResponse(outcome.row));
  } else {
    send(res, 201, jobResponse(outcome.row));
  }
}

function insertJob(key: string | null, values: ValidJob, payload: string): JobRow {
  const id = randomUUID();
  const now = nowIso();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                       idempotency_key, payload, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
  ).run(id, values.input, values.steps, values.failAttempts, key, payload, now, now);
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
}

/** Runs fn inside a BEGIN IMMEDIATE transaction, rolling back if it throws. */
function inTransaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

function health(res: ServerResponse): void {
  const row = db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1').get() as
    | { last_seen: number }
    | undefined;
  const up = row !== undefined && Date.now() - row.last_seen < HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(jobResponse) });
}

function getJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  send(res, 200, jobResponse(row));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);

  let allowed: string[] | undefined;
  if (pathname === '/') allowed = ['GET'];
  else if (pathname === '/health') allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  else if (jobMatch) allowed = ['GET'];

  if (!allowed) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  if (!allowed.includes(method)) {
    res.setHeader('allow', allowed.join(', '));
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
  } else if (pathname === '/health') {
    health(res);
  } else if (pathname === '/api/jobs') {
    if (method === 'POST') await createJob(req, res);
    else listJobs(res);
  } else {
    getJob(res, jobMatch![1]!);
  }
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Unexpected error.');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  const finish = (): void => {
    db.close();
    process.exit(0);
  };
  server.close(finish);
  server.closeAllConnections();
  setTimeout(finish, 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

