import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, nowIso, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 100;
const HEARTBEAT_MS = 1000;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const TRANSIENT_ERROR = 'transient failure';

const db = openDatabase();
let stopping = false;

function heartbeat(): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, last_seen) VALUES (1, ?)
     ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen`,
  ).run(Date.now());
}

/**
 * Returns jobs left in `running` to the queue. Only one worker runs at a time, so any `running`
 * row belongs to a worker that is gone. The interrupted attempt still counts in `attempts`,
 * because it was started.
 */
function requeueRunning(): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ?
     WHERE status = 'running'`,
  ).run(nowIso());
}

/** Runs fn inside a BEGIN IMMEDIATE transaction. Never call this across an await. */
function inTransaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

/** Claims the oldest runnable queued job and marks it running, starting a new attempt. */
function claimNext(): JobRow | undefined {
  return inTransaction(() => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as JobRow | undefined;
    if (!row) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
       WHERE seq = ?`,
    ).run(nowIso(), row.seq);
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  });
}

/**
 * Processes one attempt of a claimed job. If `stopping` becomes true part way through, the job is
 * left as `running`; the shutdown path then requeues it.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE seq = ?`,
      ).run(TRANSIENT_ERROR, nowIso(), job.seq);
    } else {
      db.prepare(`UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE seq = ?`).run(
        Date.now() + RETRY_DELAY_MS,
        nowIso(),
        job.seq,
      );
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?`).run(
      step,
      nowIso(),
      job.seq,
    );
  }

  if (stopping) return;
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, updated_at = ?
     WHERE seq = ?`,
  ).run(job.input.toUpperCase(), job.steps, nowIso(), job.seq);
}

function requestStop(): void {
  stopping = true;
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);
requeueRunning();

console.log('worker started');
while (!stopping) {
  const job = claimNext();
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeatTimer);
requeueRunning();
db.close();
console.log('worker stopped');
process.exit(0);

